from solution import words_string
import re
from hypothesis import given, assume
import hypothesis.strategies as st


def reference_words_string(s):
    """Obviously-correct reference: split on ',' or ' ' dropping empties."""
    res = []
    cur = []
    for ch in s:
        if ch == ',' or ch == ' ':
            if cur:
                res.append(''.join(cur))
                cur = []
        else:
            cur.append(ch)
    if cur:
        res.append(''.join(cur))
    return res


# ---- explicit spec examples ----
def test_spec_example_hi_my_name():
    assert words_string("Hi, my name is John") == ["Hi", "my", "name", "is", "John"]


def test_spec_example_one_to_six():
    assert words_string("One, two, three, four, five, six") == ["One", "two", "three", "four", "five", "six"]


# ---- explicit boundary / delimiter examples derived from spec ----
def test_empty_string_returns_empty():
    assert words_string("") == []


def test_only_spaces_returns_empty():
    assert words_string("   ") == []


def test_only_commas_returns_empty():
    assert words_string(",,,") == []


def test_only_mixed_delimiters_returns_empty():
    assert words_string(" , , , ") == []


def test_single_word_no_delimiters():
    assert words_string("Hello") == ["Hello"]


def test_comma_without_space_splits():
    # commas separate words even with no spaces
    assert words_string("One,two") == ["One", "two"]
    assert words_string("a,b,c") == ["a", "b", "c"]
    assert words_string("Hi,my,name,is,John") == ["Hi", "my", "name", "is", "John"]


def test_consecutive_commas_without_spaces():
    assert words_string("a,,b") == ["a", "b"]
    assert words_string("a,,,b") == ["a", "b"]


def test_leading_trailing_delimiters():
    assert words_string("  Hello  ") == ["Hello"]
    assert words_string(",Hello,") == ["Hello"]
    assert words_string(" , Hello , ") == ["Hello"]


def test_multiple_spaces():
    assert words_string("a  b   c") == ["a", "b", "c"]


# ---- property tests ----
@given(st.text(alphabet="abcXYZ012 ,", max_size=20))
def test_property_reference_model_equivalence(s):
    assert words_string(s) == reference_words_string(s)


@given(st.text(alphabet="abcXYZ012 ,!?.-_", max_size=20))
def test_property_no_empty_tokens(s):
    for w in words_string(s):
        assert w != ""


@given(st.text(alphabet="abcXYZ012 ,!?.-_", max_size=20))
def test_property_no_delimiters_inside_tokens(s):
    for w in words_string(s):
        assert "," not in w
        assert " " not in w


@given(st.text(alphabet="abcXYZ012 ,", max_size=20))
def test_property_concatenation_coverage(s):
    # removing delimiters from input equals concatenating output words
    stripped = s.replace(",", "").replace(" ", "")
    assert "".join(words_string(s)) == stripped


@given(st.text(alphabet="abXY01 ,", max_size=20))
def test_property_comma_space_interchangeable(s):
    # ',' and ' ' are both separators, swapping them preserves split
    a = words_string(s)
    b = words_string(s.replace(",", " "))
    c = words_string(s.replace(" ", ","))
    assert a == b
    assert a == c


@given(st.lists(st.text(alphabet="abcXYZ012", min_size=1, max_size=5), max_size=6))
def test_property_join_roundtrip(words):
    # joining clean words with any delimiter mix must round-trip
    assert words_string(" ".join(words)) == words
    assert words_string(",".join(words)) == words
    assert words_string(", ".join(words)) == words
    assert words_string(" , ".join(words)) == words


@given(st.text(alphabet="abcXYZ012 ,", max_size=20))
def test_property_extra_delimiters_idempotent(s):
    # re-joining the result with single spaces is a fixed point
    first = words_string(s)
    assert words_string(" ".join(first)) == first
    assert words_string(",".join(first)) == first
    # padding with delimiters does not change result
    assert words_string("  " + s + "  ") == first
    assert words_string(",," + s + ",,") == first
